draw:
function draw(ctx, t, W, H) {
  ctx.save();
  ctx.fillStyle = '#f5f0e8';
  ctx.fillRect(0, 0, W, H);
  ctx.lineWidth = 3;
  ctx.strokeStyle = 'black';
  for (let i = 0; i < 10; i++) {
    ctx.beginPath();
    ctx.arc(W / 2 + Math.sin(t + i) * 100, H / 2 + Math.cos(t + i * 1.1) * 50, 10, 0, 2 * Math.PI);
    ctx.stroke();
    ctx.beginPath();
    ctx.moveTo(W / 2 + Math.sin(t + i) * 100, H / 2 + Math.cos(t + i * 1.1) * 50);
    ctx.lineTo(W / 2 + Math.sin(t + i) * 100 + Math.cos(t + i) * 20, H / 2 + Math.cos(t + i * 1.1) * 50 + Math.sin(t + i) * 10);
    ctx.stroke();
    ctx.beginPath();
    ctx.moveTo(W / 2 + Math.sin(t + i) * 100, H / 2 + Math.cos(t + i * 1.1) * 50);
    ctx.lineTo(W / 2 + Math.sin(t + i) * 100 + Math.cos(t + i) * 20, H / 2 + Math.cos(t + i * 1.1) * 50 - Math.sin(t + i) * 10);
    ctx.stroke();
  }
  ctx.restore();
}
